bounded_host_request.command:
set -euo pipefail
root="$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
original=gace-tgtumbler-gaybbs:local
candidate=gace-tgtumbler-gaybbs:link-pr62-4a1c5be3
rollback=gace-tgtumbler-gaybbs:rollback-pr62-20261120
test "$(systemctl --user is-active gace-userbot-verify.service)" = active || exit 61
old_id="$(docker image inspect -f '{{.Id}}' "$rollback")" || exit 62
new_id="$(docker image inspect -f '{{.Id}}' "$candidate")" || exit 63
test "$(docker inspect -f '{{.State.Running}}' deploy-gaybbs-1)" = true || exit 64
test "$(docker inspect -f '{{.Image}}' deploy-gaybbs-1)" = "$old_id" || exit 65
test "$(docker image inspect -f '{{.Id}}' "$original")" = "$old_id" || exit 66
test "$old_id" != "$new_id" || exit 67
rollback_live(){
 docker tag "$rollback" "$original"
 docker compose -p deploy -f "$root/deploy/gserver-compose.yaml" up -d --no-deps --force-recreate gaybbs >/dev/null 2>&1 || true
}
trap rollback_live ERR
docker tag "$candidate" "$original"
docker compose -p deploy -f "$root/deploy/gserver-compose.yaml" up -d --no-deps --force-recreate gaybbs >/dev/null
sleep 9
test "$(docker inspect -f '{{.State.Running}}' deploy-gaybbs-1)" = true || exit 68
test "$(docker inspect -f '{{.Image}}' deploy-gaybbs-1)" = "$new_id" || exit 69
docker exec deploy-gaybbs-1 node --import /app/preload/telegram-ipv4-preload.mjs --input-type=module -e '
import fs from "node:fs";
const p=process.env.BOT_TOKEN_FILE;
const token=p?fs.readFileSync(p,"utf8").trim():process.env.BOT_TOKEN;
if(!token)process.exit(51);
let ok=false;
for(let i=0;i<2;i++)try{
 const r=await fetch("https://api.telegram.org/bot"+token+"/getMe",{signal:AbortSignal.timeout(12000)});
 const j=await r.json();
 if(j.ok&&j.result.username==="GayBBS_bot"){ok=true;break}
}catch{}
if(!ok)process.exit(52)
' || exit 70
test "$(systemctl --user is-active gace-userbot-verify.service)" = active || exit 71
trap - ERR
echo LINK_BOT_IMAGE_REPLACED=PASS
echo TELEGRAM_BOT_API=PASS
echo USERBOT_SESSION_OWNER=ACTIVE
echo LINK_BOT_IMAGE_ROLLBACK_RETAINED=PASS
